function setStage(k, o, to, extra = {}) {
  const isOpp = k === 'opp', from = o.stage, prev = {stage: o.stage, reason: o.reason, reviewDate: o.reviewDate, win: o.win}, m = me();
  const lbl = s => isOpp ? (s === 'active' ? oppDef({...o, stage: 'active'})[0] : OPP[s][0]) : REL[s][0];
  o.stage = to; if (extra.reason != null) o.reason = extra.reason; if ('reviewDate' in extra) o.reviewDate = extra.reviewDate; if (extra.win) o.win = extra.win;
  if (isOpp) o.history.push({stage: to, by: m.id, at: nowStamp(), reason: extra.reason || ''});
  logChange(EE, 'changed the stage of', isOpp ? oppLink(o) : orgLink(o), lbl(from), lbl(to));
  if (isOpp && o.pic !== m.id) upd(o.pic, 'ee-stage', o.title, `opportunities/${o.id}`);
  ui.insp = null; ui.form = null; save(); render();
  // Undo appends the reverse step to the stage history (work_undo_archive).
  toast(L('Stage changed to {s}', {s: L(lbl(to))}), () => { Object.assign(o, prev); if (isOpp) o.history.push({stage: from, by: m.id, at: nowStamp(), reason: L('Undone')}); logChange(EE, 'changed the stage of', isOpp ? oppLink(o) : orgLink(o), lbl(to), lbl(from)); rerender(); });
}
function closeFu(t, ixId) { t.status = 'done'; t.doneAt = today(); t.finishedAt = nowStamp(); logChange(EE, 'completed', {type: 'task', id: t.id, name: t.title}); }

