  const scopeBox = s => s ? `<div class="quiet ec-scope"><div class="row-wrap ec-between"><b>${L('Scope version {v}', {v: s.v})}</b>${chip(SCOPE.approved)}</div><p>${esc(s.goal || p.goal)}</p>
    <div class="grid2"><div><small class="t-mute">${L('In scope')}</small><ul>${(s.in || []).map(x => `<li>${esc(x)}</li>`).join('')}</ul></div><div><small class="t-mute">${L('Out of scope')}</small><ul>${(s.out || []).map(x => `<li>${esc(x)}</li>`).join('') || `<li class="t-mute">${L('None listed')}</li>`}</ul></div></div>
    ${s.criteria ? `<p><small class="t-mute">${L('Acceptance criteria')}</small><br>${esc(s.criteria)}</p>` : ''}<small class="t-mute">${L('Proposed by {who}', {who: byAt(s.by, s.at)})}${s.decidedBy ? `. ${L('Approved by {who}', {who: byAt(s.decidedBy, s.decidedAt)})}` : ''}</small></div>`
    : note('warn', 'warning', L('No approved scope yet'), L('Deliverables can’t be ready until a scope version is approved.'));
