// ---------- Knowledge (consulting_knowledge, W064, S058, S059) ----------
const artOf = id => CN().kn.find(a => a.id === id);
const pubV = a => a.versions.filter(v => v.state === 'published').slice(-1)[0] || null;
const isCurator = m => !!m && m.div === CONS && !isBoard(m) && (branchOf(m) === 'kn' || rk(m) >= 3);
const artStaff = (a, m) => !!m && (a.author === m.id || a.owner === m.id || (a.audience !== 'named' && isCurator(m)));
// Restricted articles stay invisible, title included, to anyone outside their audience (resource_search, no disclosure).
const canSeeArt = (a, m) => { if (!m || isBoard(m)) return false; if (a.audience === 'named') return a.named.includes(m.id) || a.owner === m.id || a.author === m.id; if (artStaff(a, m)) return true; if (!pubV(a)) return false; return a.audience === 'org' || (a.audience === 'cons' && (m.div === CONS || isTop(m) || m.admin)); };
const artLink = a => tgt('cons', a.id, a.title, `knowledge/${a.id}`);
