// ---------- the same records inside shared views ----------
// The task panel shows where an EE follow-up or a Consulting revision task comes from, so the PIC sees one record in every view (external_followup).
if (INSP.task) { const base = INSP.task;
  INSP.task = x => { let out = base(x); try { ensure(); const t = taskOf(x.id), m = me(); if (!t || !m) return out; const f = fuOf(t.id);
    if (f && seeDiv(m, EE)) { const o = orgOf(f.org), op = f.opp && oppOf(f.opp), n = attempts(f);
      out += `<h3 class="sec-h">${L('External Engagement')}</h3>${meta([[L('Relationship'), o ? `<a href="#/relationships/${o.id}">${esc(o.name)}</a>` : '-'], op ? [L('Opportunity'), `<a href="#/opportunities/${op.id}">${esc(op.title)}</a>`] : null, f.outcome ? [L('Requested outcome'), esc(f.outcome)] : null, [L('Channel'), esc(L(CHANNEL[f.channel] || 'Other'))], [L('Attempts'), String(n)]])}
        ${!isDone(t) && eeMember(m) ? `<div class="acts">${btn('ec-fu-done', L('Record outcome'), `data-id="${t.id}"`, 'btn-pri btn-sm')}${btn('ec-postpone', L('Postpone'), `data-id="${t.id}"`, 'btn-sm')}</div>` : ''}`; }
    const d = CN().dlv.find(z => z.versions.some(v => v.review && v.review.task === t.id));
    if (d && canSeeEng(projOf(d.project), m)) { const v = d.versions.find(z => z.review && z.review.task === t.id); out += `<h3 class="sec-h">${L('Revision')}</h3><p class="t-small">${L('Requested on {t}, version {v}', {t: `<a href="#/engagements/${d.project}/${d.id}">${esc(d.title)}</a>`, v: v.v})}</p>${v.review.note ? `<p class="quote">${esc(v.review.note)}</p>` : ''}<p class="t-small t-mute">${L('Closing this task does not approve anything. Submit a new version for review.')}</p>`; }
  } catch (e) { /* the shared panel must keep working even if this addition fails */ } return out; }; }

// Updates and Changes rows for these records carry their route in ref.h / target.h. plan.js knows only core record types, so the two views
// are wrapped, as div-hr-sng.js does; double wrapping is harmless because each wrapper only fills what is still missing.
