  'cons-dlv-review': '{who} sent a deliverable for your review', 'cons-dlv-ok': '{who} approved your deliverable', 'cons-dlv-ret': '{who} asked for changes to your deliverable', 'cons-dlv-owner': '{who} made you the owner of a deliverable',
  'cons-scope': '{who} asked you to decide a scope change', 'cons-scope-ok': '{who} approved your scope change', 'cons-scope-no': '{who} rejected your scope change', 'cons-stale': '{who} changed the scope; your approval is stale',
