if (PAGES.updates) { const base = PAGES.updates;
  PAGES.updates = r => { const out = base(r); const gone = `<span class="t-mute">${L('No longer available')}</span>`;
    db.updates.filter(u => u.to === session.me && u.ref && u.ref.h).forEach(u => { const i = out.content.indexOf(`data-id="${u.id}"`); if (i < 0) return; const j = out.content.indexOf(gone, i), k = out.content.indexOf('data-act="open-update"', i + 10);
      if (j < 0 || (k >= 0 && j > k)) return; out.content = out.content.slice(0, j) + esc(u.ref.title || '') + out.content.slice(j + gone.length); });
    return out; }; }
if (ACT['open-update']) { const base = ACT['open-update'];
  ACT['open-update'] = (el, id, e) => { const u = db.updates.find(v => v.id === id); if (u && u.ref && u.ref.h) { u.read = true; save(); ui.insp = null; ui.form = null; go(u.ref.h); return; } return base(el, id, e); }; }
if (typeof chgRow === 'function') { const base = chgRow;
  window.chgRow = c => { const t = c.target || {}; if (!t.h) return base(c);
    return `<div class="chg">${av(c.actor, 'av-sm')}<div class="chg-t"><b>${esc(pname(c.actor))}</b> ${esc(L(c.verb))} <a class="rec" href="#/${esc(t.h)}">${esc(t.name)}</a>${c.from || c.to ? `<div class="diff">${c.from ? `<span class="tag tag-outline">${esc(L(c.from))}</span>` : ''}<span class="to">→</span>${c.to ? `<span class="tag">${esc(L(c.to))}</span>` : ''}</div>` : ''}</div><time>${c.at.slice(11, 16)}</time></div>`; }; }

